import 'package:flutter/material.dart';
import '../core/database/database_helper.dart';

class ProductsScreen extends StatefulWidget{const ProductsScreen({super.key});@override State<ProductsScreen> createState()=>_ProductsState();}
class _ProductsState extends State<ProductsScreen>{final barcode=TextEditingController(),name=TextEditingController(),qty=TextEditingController(),buy=TextEditingController(),sell=TextEditingController();Future<void> add()async{if(name.text.trim().isEmpty)return;await DatabaseHelper.instance.insert('products',{'barcode':barcode.text,'name':name.text,'quantity':double.tryParse(qty.text)??0,'purchase_price':double.tryParse(buy.text)??0,'sale_price':double.tryParse(sell.text)??0,'created_at':DateTime.now().toIso8601String()});barcode.clear();name.clear();qty.clear();buy.clear();sell.clear();setState((){});}Future<void> form()=>showDialog(context:context,builder:(_)=>AlertDialog(title:const Text('إضافة صنف'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[for(final x in [[barcode,'الباركود'],[name,'اسم الصنف'],[qty,'الكمية'],[buy,'سعر الشراء'],[sell,'سعر البيع']])TextField(controller:x[0] as TextEditingController,keyboardType:x[1]=='الكمية'||x[1]=='سعر الشراء'||x[1]=='سعر البيع'?TextInputType.number:TextInputType.text,decoration:InputDecoration(labelText:x[1] as String))])),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('إلغاء')),FilledButton(onPressed:()async{await add();if(mounted)Navigator.pop(context);},child:const Text('حفظ'))]));@override Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(12),children:[Align(alignment:Alignment.centerLeft,child:FilledButton.icon(onPressed:form,icon:const Icon(Icons.add_box),label:const Text('إضافة صنف'))),FutureBuilder(future:DatabaseHelper.instance.all('products'),builder:(c,s){final rows=s.data??[];return rows.isEmpty?const Card(child:Padding(padding:EdgeInsets.all(28),child:Center(child:Text('لا توجد أصناف')))):SingleChildScrollView(scrollDirection:Axis.horizontal,child:DataTable(columns:const[DataColumn(label:Text('الباركود')),DataColumn(label:Text('الصنف')),DataColumn(label:Text('الكمية')),DataColumn(label:Text('سعر الشراء')),DataColumn(label:Text('سعر البيع'))],rows:rows.map((r)=>DataRow(cells:[DataCell(Text(r['barcode']??'')),DataCell(Text(r['name'])),DataCell(Text('${r['quantity']}')),DataCell(Text('${r['purchase_price']}')),DataCell(Text('${r['sale_price']}'))])).toList()));})]);}
}
